A count distinguishes full from empty even when the read and write positions coincide, so all 17 slots are usable. Push rejects overflow without changing the queue, and pop rejects an empty queue without changing its output argument. This complete C++17 program also tests wraparound while data remains queued.

```cpp
#include <array>
#include <cassert>
#include <cstddef>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -99;
    assert(!queue.pop(value));
    assert(value == -99);

    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
    }
    assert(!queue.push(999));
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(!queue.pop(value));

    // Fill, partially drain, then wrap the write position.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
    }
    for (int i = 0; i < 8; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 17; i < 25; ++i) {
        assert(queue.push(i));
    }
    assert(!queue.push(999));
    for (int i = 8; i < 25; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(!queue.pop(value));
}
```

