A lane with no partner selects itself as the shuffle source; it does not skip the collective. In the original code:
```cpp
const unsigned partner = lane + static_cast<unsigned>(offset);
const bool has_partner = partner < 19u;
const int source = static_cast<int>(has_partner ? partner : lane);

const float other = __shfl_sync(mask, sum, source, 32);
if (has_partner) {
    sum = __fadd_rn(sum, other);
}
```
When `has_partner` is false, `source` is exactly `lane`. Under the original contract, every caller is a physical lane from 0 through 18, and `mask = 0x0007ffffu` names exactly those lanes. That lane therefore names a participating source— itself—and executes the same shuffle as every other named lane, with the same mask and width 32.

For example, lane 18 has no partner at any offset: its proposed partners are 34, 26, 22, 20, and 19 for offsets 16, 8, 4, 2, and 1. Each fails `partner < 19u`, so each shuffle reads lane 18’s own current `sum`. But the addition is guarded by `if (has_partner)`, which is false each time: `other` is discarded, and lane 18’s accumulator remains its original input rather than doubling it.

Finally, lane 18 executes the original broadcast, `return __shfl_sync(mask, sum, 0, 32);`, and returns lane 0’s completed reduction. That final operation replaces the returned value; it does not add lane 18’s local accumulator again. Thus the self-read introduces no duplicate contribution.

The original kernel violates the block-barrier contract: a conditional `__syncthreads()` must have a condition uniform across the block. With 96 threads and `valid == 70`, threads 0–69 execute the barrier while threads 70–95 skip the guarded region. That is undefined behavior, not a guarantee that every device hangs; successful immediate launch checks establish neither synchronization correctness nor eventual GPU progress.

Move the barrier outside the conditional load, and let thread zero write the result even when `valid == 0`.

```cpp
// sum_valid.cu
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t status, const char* operation)
{
    if (status != cudaSuccess) {
        std::fprintf(stderr, "%s: %s\n", operation,
                     cudaGetErrorString(status));
        std::exit(EXIT_FAILURE);
    }
}
#define CHECK(call) check((call), #call)

__global__ void sum_valid(const float* input, float* output, int valid)
{
    // Contract: exactly <<<1, 96>>>; 0 <= valid <= 96.
    // input contains at least valid readable floats;
    // output contains one writable float, separate from input.
    __shared__ float values[96];
    const unsigned tid = threadIdx.x;

    float value = 0.0f;
    if (tid < static_cast<unsigned>(valid)) {
        value = input[tid];
    }
    values[tid] = value;

    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum = __fadd_rn(sum, values[i]);
        }
        output[0] = sum;
    }
}

int main(int argc, char** argv)
{
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        long parsed = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' || parsed < 0 || parsed > 96) {
            std::fprintf(stderr, "valid must be 0..96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(parsed);
    }

    cudaStream_t stream;
    cudaEvent_t done;
    CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CHECK(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));

    float *host_input, *host_output, *device_input, *device_output;
    CHECK(cudaMallocHost(reinterpret_cast<void**>(&host_input),
                         96 * sizeof(float)));
    CHECK(cudaMallocHost(reinterpret_cast<void**>(&host_output),
                         sizeof(float)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_input),
                     96 * sizeof(float)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_output),
                     sizeof(float)));

    for (int i = 0; i < 96; ++i) host_input[i] = float(i + 1);
    if (valid > 0) {
        CHECK(cudaMemcpyAsync(device_input, host_input,
                              valid * sizeof(float),
                              cudaMemcpyHostToDevice, stream));
    }
    // Always launch, including valid == 0. No host output initialization.
    sum_valid<<<1, 96, 0, stream>>>(device_input, device_output, valid);
    CHECK(cudaGetLastError()); // Immediate launch errors only.
    CHECK(cudaMemcpyAsync(host_output, device_output, sizeof(float),
                          cudaMemcpyDeviceToHost, stream));
    CHECK(cudaEventRecord(done, stream));
    CHECK(cudaEventSynchronize(done)); // Completion and asynchronous errors.

    const float expected = float(valid * (valid + 1) / 2);
    const bool correct = (*host_output == expected);
    std::printf("valid=%d sum=%.9g expected=%.9g\n",
                valid, *host_output, expected);

    CHECK(cudaFree(device_input));
    CHECK(cudaFree(device_output));
    CHECK(cudaFreeHost(host_input));
    CHECK(cudaFreeHost(host_output));
    CHECK(cudaEventDestroy(done));
    CHECK(cudaStreamDestroy(stream));
    return correct ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

