#include <cuda_runtime.h>

// Contract: all 32 lanes of a full warp call this function
// for the same invocation; none exits before the ballot.
__device__ __forceinline__ float broadcast_lane18(float value)
{
    unsigned lane;
    asm("mov.u32 %0, %%laneid;" : "=r"(lane));

    const bool participating = lane <= 18u;
    const unsigned mask = __ballot_sync(0xffffffffu, participating);

    if (participating) {
        value = __shfl_sync(mask, value, 18, 32);
    }
    return value;
}
