Use one shuffle to pair lanes 16–18 with lanes 0–2, then four butterfly shuffles that compute the sum in every caller. This uses five float shuffles per caller, with no final broadcast, shared memory, atomics, or implicit lockstep assumption.

```cpp
// sum19.cu
#include <cuda_runtime.h>

// Contract: Volta or newer; exactly physical lanes 0..18 of
// one warp call once for the same invocation. None exits early.
__device__ __forceinline__ float sum19(float value)
{
    unsigned lane;
    asm("mov.u32 %0, %%laneid;" : "=r"(lane));

    constexpr unsigned mask = 0x0007ffffu;
    const unsigned rank = lane < 16u ? lane : lane - 16u;

    const unsigned source = lane < 3u ? lane + 16u
                          : lane >= 16u ? lane - 16u
                          : lane;
    const float other = __shfl_sync(mask, value, source, 32);

    float sum = value;
    if (lane < 3u) {
        sum = __fadd_rn(value, other);
    } else if (lane >= 16u) {
        sum = __fadd_rn(other, value);
    }

    #pragma unroll
    for (unsigned bit = 1u; bit <= 8u; bit <<= 1) {
        const unsigned partner = rank ^ bit;
        const float peer = __shfl_sync(mask, sum, partner, 32);
        sum = (rank & bit) == 0u
            ? __fadd_rn(sum, peer)
            : __fadd_rn(peer, sum);
    }
    return sum;
}
```

