A count distinguishes full from empty even when the read and write positions coincide, so all 17 slots are usable. Push rejects overflow without changing the queue, and an empty pop leaves its output argument unchanged. This complete C++17 program tests those guarantees, FIFO ordering, and wraparound while entries remain queued.

```cpp
#include <array>
#include <cassert>
#include <cstddef>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO q;
    int value = -123;
    assert(!q.pop(value));
    assert(value == -123);

    for (int i = 0; i < 17; ++i) assert(q.push(i));
    assert(!q.push(999));
    for (int i = 0; i < 17; ++i) {
        assert(q.pop(value));
        assert(value == i);
    }
    assert(!q.pop(value));
    assert(value == 16);

    // Keep seven entries queued while the write position wraps.
    for (int i = 0; i < 17; ++i) assert(q.push(i));
    for (int i = 0; i < 10; ++i) {
        assert(q.pop(value));
        assert(value == i);
    }
    for (int i = 17; i < 27; ++i) assert(q.push(i));
    assert(!q.push(999));
    for (int i = 10; i < 27; ++i) {
        assert(q.pop(value));
        assert(value == i);
    }
    assert(!q.pop(value));
    assert(value == 26);
}
```

