B’s wait references the first record of E, the record current when the wait was submitted. Interpreting “weight” as “wait” and “save first use” as “safe first use,” the second record does not retarget that wait; the later query checks the second record. P2 can race with C1 because neither stream establishes C1-before-P2 ownership ordering.

A permitted trace is:
1. The host submits P1 and E’s first record to A, then B’s wait and C1, then P2 and E’s second record to A.
2. P1 finishes writing value 1; E’s first record completes, satisfying B’s wait.
3. C1 is eligible but has not read yet. P2 starts overwriting the allocation. A query of E returns not ready because its second record has not completed.
4. P2 finishes writing value 2, then C1 reads value 2 instead of its intended generation 1. This execution respects both streams’ ordering. Overlapping reads and writes are also possible; there is no correctness guarantee.

Use two allocations, each with ready and consumed events. A slot transitions from producer-owned to consumer-readable at ready completion, then back to reusable at consumed completion. The host submits the wait on the previous consumed record before rerecording that event, and submits B’s ready wait before rerecording ready. First use skips the consumed wait because no previous consumer exists.

```cpp
// ownership.cu
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t status, const char* call)
{
    if (status != cudaSuccess) {
        std::fprintf(stderr, "%s: %s\n", call,
                     cudaGetErrorString(status));
        std::exit(EXIT_FAILURE);
    }
}
#define CHECK(call) check((call), #call)

__global__ void producer(int* slot, int value)
{
    *slot = value;
}

__global__ void consumer(const int* slot, int* result)
{
    *result = *slot;
}

int main()
{
    constexpr int iterations = 8;
    cudaStream_t A, B;
    CHECK(cudaStreamCreateWithFlags(&A, cudaStreamNonBlocking));
    CHECK(cudaStreamCreateWithFlags(&B, cudaStreamNonBlocking));

    struct Slot {
        int* data = nullptr;
        cudaEvent_t ready{};
        cudaEvent_t consumed{};
        bool used = false;
    };
    Slot slots[2];
    for (auto& slot : slots) {
        CHECK(cudaMalloc(reinterpret_cast<void**>(&slot.data), sizeof(int)));
        CHECK(cudaEventCreateWithFlags(&slot.ready, cudaEventDisableTiming));
        CHECK(cudaEventCreateWithFlags(&slot.consumed,
                                       cudaEventDisableTiming));
    }

    int* results = nullptr;
    CHECK(cudaMalloc(reinterpret_cast<void**>(&results),
                     iterations * sizeof(int)));

    for (int i = 0; i < iterations; ++i) {
        Slot& slot = slots[i % 2];

        // Capture the previous consumed record before its next rerecord.
        // First use has no previous consumer.
        if (slot.used) {
            CHECK(cudaStreamWaitEvent(A, slot.consumed, 0));
        }

        producer<<<1, 1, 0, A>>>(slot.data, i + 1);
        CHECK(cudaGetLastError());
        CHECK(cudaEventRecord(slot.ready, A));

        // Capture this generation's ready record before its next rerecord.
        CHECK(cudaStreamWaitEvent(B, slot.ready, 0));
        consumer<<<1, 1, 0, B>>>(slot.data, results + i);
        CHECK(cudaGetLastError());
        CHECK(cudaEventRecord(slot.consumed, B));
        slot.used = true;
    }

    // Final drain only; no host synchronization between iterations.
    // No device-wide synchronization is used.
    CHECK(cudaStreamSynchronize(B));
    CHECK(cudaStreamSynchronize(A));

    int host_results[iterations];
    CHECK(cudaMemcpy(host_results, results, sizeof(host_results),
                     cudaMemcpyDeviceToHost));
    bool correct = true;
    for (int i = 0; i < iterations; ++i) {
        if (host_results[i] != i + 1) {
            std::fprintf(stderr, "iteration %d: got %d, expected %d\n",
                         i, host_results[i], i + 1);
            correct = false;
        }
    }

    for (auto& slot : slots) {
        CHECK(cudaEventDestroy(slot.ready));
        CHECK(cudaEventDestroy(slot.consumed));
        CHECK(cudaFree(slot.data));
    }
    CHECK(cudaFree(results));
    CHECK(cudaStreamDestroy(A));
    CHECK(cudaStreamDestroy(B));
    if (correct) std::puts("All results correct");
    return correct ? EXIT_SUCCESS : EXIT_FAILURE;
}
